// ReproduceTagSize.js
import React from 'react';
import ReactDOM from 'react-dom';
import { DataTable, Table, TableHead, TableRow, TableHeader, TableBody, TableCell, Tag } from 'carbon-components-react';
import './short-tag.css';

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
  { key: 'tags', header: 'Tags' },
];

const rows = [
  {
    id: 'a',
    name: 'Server A',
    status: 'Running',
    tags: [<Tag key="1" type="gray">Default</Tag>],
  },
  {
    id: 'b',
    name: 'Server B',
    status: 'Stopped',
    // Demonstrate the short/compact tag by adding 'short-tag' class
    tags: [<Tag key="2" type="gray" className="bx--tag--short">Compact</Tag>],
  },
];

function ReproduceTagSize() {
  return (
    <div style={{ width: '600px', margin: '20px' }}>
      <h4>Default Tag (24px height)</h4>
      <DataTable rows={rows.map(r => ({ ...r, tags: r.tags[0] }))} headers={headers}>
        {({ rows, headers, getTableProps, getHeaderProps, getRowProps }) => (
          <Table {...getTableProps()} size="compact">
            <TableHead>
              <TableRow>
                {headers.map(h => (
                  <TableHeader key={h.key} {...getHeaderProps({ header: h })}>{h.header}</TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>
                      {/* if this is the tags column, render the prebuilt Tag component */}
                      {cell.info.header === 'Tags' ? rows.find(r => r.id === row.id).tags : cell.value}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </DataTable>

      <h4>Short Tag Override (18px height)</h4>
      <Tag type="gray" className="bx--tag--short">Short Tag</Tag>
      <Tag type="gray" className="bx--tag--short" filter>
        Short Tag
      </Tag>
    </div>
  );
}

ReactDOM.render(<ReproduceTagSize />, document.getElementById('root'));

1.explanation:
1. We import the default 24px tall <Tag> from Carbon and render it inside a compact DataTable row to show the overflow.  
2. We add a CSS override in short-tag.css to reduce the overall height to 18px and preserve the horizontal padding of 8px:  

```css
/* short-tag.css */
.bx--tag--short {
  min-height: 18px;
  height: 18px;
  padding: 0 8px;
}
.bx--tag--short .bx--tag__label,
.bx--tag--short .bx--tag__close-icon {
  line-height: 18px;
}
```

3. We apply the custom className "bx--tag--short" to the Tag to demonstrate the proposed 18px tall variant, which fits neatly into a compact/short row height.  

This snippet reproduces the bug (overflowing 24px tag) and demonstrates the fix (an 18px short tag) side by side.
